#!/usr/bin/env node
/**
 * figma-check.mjs
 *
 * Preflight único para validar se o projeto está pronto para trabalhar em modo Figma.
 * Verifica:
 * - existência de dock-ds.config.json
 * - configuração mínima da seção figma
 * - presença de FIGMA_TOKEN e FIGMA_FILE_ID (env ou .env.local/.env)
 * - acesso ao arquivo Figma via API
 * - artefatos básicos do modo Figma
 *
 * Uso:
 *   npm run figma:check
 *   node node_modules/@dock-tech/shared-copilot-front-lib/scripts/figma-check.mjs
 */

import { existsSync, readFileSync } from 'fs';
import { join } from 'path';

const CWD = process.cwd();
const FIGMA_API_BASE = 'https://api.figma.com/v1';

function parseEnvFile(filePath) {
  if (!existsSync(filePath)) return {};

  const content = readFileSync(filePath, 'utf-8');
  const env = {};

  for (const rawLine of content.split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith('#')) continue;

    const separatorIndex = line.indexOf('=');
    if (separatorIndex === -1) continue;

    const key = line.slice(0, separatorIndex).trim();
    const value = line.slice(separatorIndex + 1).trim().replace(/^['"]|['"]$/g, '');
    env[key] = value;
  }

  return env;
}

function loadEnv() {
  return {
    ...parseEnvFile(join(CWD, '.env')),
    ...parseEnvFile(join(CWD, '.env.local')),
    ...process.env,
  };
}

function ok(message) {
  console.log(`✅ ${message}`);
}

function warn(message) {
  console.log(`⚠️  ${message}`);
}

function fail(message) {
  console.log(`❌ ${message}`);
}

function summaryLine(label, status, detail) {
  const icon = status === 'ok' ? '✅' : status === 'warn' ? '⚠️ ' : '❌';
  console.log(`${icon} ${label}: ${detail}`);
}

async function canAccessFigmaFile(token, fileId) {
  const response = await fetch(`${FIGMA_API_BASE}/files/${fileId}?depth=1`, {
    headers: { 'X-Figma-Token': token },
  });

  if (!response.ok) {
    const body = await response.text();
    throw new Error(`Figma API ${response.status}: ${body}`);
  }

  const data = await response.json();
  return {
    name: data.name,
    lastModified: data.lastModified,
  };
}

async function main() {
  console.log('═'.repeat(60));
  console.log('  🧪 Figma Check — Preflight do Projeto');
  console.log('═'.repeat(60));

  const env = loadEnv();
  const configPath = join(CWD, 'dock-ds.config.json');
  const designDocPath = join(CWD, 'DESIGN_SYSTEM.md');
  const nodeDataPath = join(CWD, 'figma-node-data.json');

  let hardFailures = 0;
  let warnings = 0;
  let config = null;

  if (!existsSync(configPath)) {
    fail('dock-ds.config.json não encontrado. Este projeto ainda não está configurado para o fluxo Figma.');
    console.log('   Ação: criar o arquivo com a seção `figma` ou inicializar via template/config compartilhado.');
    hardFailures++;
  } else {
    config = JSON.parse(readFileSync(configPath, 'utf-8'));
    ok('dock-ds.config.json presente');
  }

  const configFileId = config?.figma?.fileId || null;
  const envFileId = env.FIGMA_FILE_ID || null;
  const resolvedFileId = configFileId || envFileId || null;
  const token = env.FIGMA_TOKEN || null;

  if (!config?.figma) {
    fail('Seção `figma` ausente no dock-ds.config.json.');
    console.log('   Ação: adicionar `figma.fileId`, `designSystemDoc` e `nodeDataFile` no config.');
    hardFailures++;
  } else {
    ok('Seção `figma` presente no config');
  }

  if (configFileId) {
    ok(`figma.fileId configurado no projeto (${configFileId})`);
  } else if (envFileId) {
    warn('figma.fileId ausente no config; usando FIGMA_FILE_ID do ambiente local.');
    warnings++;
  } else {
    fail('FIGMA_FILE_ID ausente. Não está no config nem no ambiente local.');
    console.log('   Ação: preencher `figma.fileId` no dock-ds.config.json ou `FIGMA_FILE_ID` no .env.local.');
    hardFailures++;
  }

  if (token) {
    ok('FIGMA_TOKEN presente');
  } else {
    fail('FIGMA_TOKEN ausente.');
    console.log('   Ação: criar `.env.local` com `FIGMA_TOKEN=figd_...`. Veja `.env.example`.');
    hardFailures++;
  }

  if (existsSync(join(CWD, '.env.example'))) {
    ok('.env.example presente');
  } else {
    warn('.env.example ausente. Novo dev não terá referência de setup local.');
    warnings++;
  }

  if (existsSync(designDocPath)) {
    ok('DESIGN_SYSTEM.md presente');
  } else {
    warn('DESIGN_SYSTEM.md ausente. Modo Figma ficará sem fonte documental local.');
    warnings++;
  }

  if (existsSync(nodeDataPath)) {
    ok('figma-node-data.json presente');
  } else {
    warn('figma-node-data.json ausente. Rode `npm run figma:sync` após passar no preflight.');
    warnings++;
  }

  let accessValidated = false;
  if (token && resolvedFileId) {
    try {
      const file = await canAccessFigmaFile(token, resolvedFileId);
      ok(`Acesso ao arquivo Figma validado (${file.name})`);
      console.log(`   Última modificação: ${file.lastModified}`);
      accessValidated = true;
    } catch (error) {
      fail(`Não foi possível acessar o arquivo Figma: ${error.message}`);
      console.log('   Ação: validar token, file id e permissões de Viewer/Dev Mode no arquivo canônico.');
      hardFailures++;
    }
  } else {
    warn('Acesso ao arquivo Figma não validado porque faltam token e/ou file id.');
    warnings++;
  }

  console.log('\n' + '─'.repeat(60));
  summaryLine('Token presente', token ? 'ok' : 'fail', token ? 'sim' : 'não');
  summaryLine('File ID presente', resolvedFileId ? 'ok' : 'fail', resolvedFileId ? 'sim' : 'não');
  summaryLine('Acesso ao arquivo', accessValidated ? 'ok' : 'fail', accessValidated ? 'ok' : 'não validado');
  summaryLine('Projeto pronto para modo Figma', hardFailures === 0 ? 'ok' : 'fail', hardFailures === 0 ? 'sim' : 'não');
  console.log('─'.repeat(60));
  console.log(`Hard failures: ${hardFailures}`);
  console.log(`Warnings: ${warnings}`);

  if (hardFailures > 0) {
    console.log('\n❌ Preflight falhou. Corrija os itens acima antes de trabalhar com Figma real.');
    process.exit(1);
  }

  console.log('\n✅ Preflight concluído. Projeto apto para fluxo Figma.');
}

main().catch((error) => {
  console.error('\n❌ Erro inesperado no figma:check:', error.message);
  process.exit(1);
});